-- Vincula cidades operacionais existentes ao catálogo
UPDATE public.cities c
SET sp_municipality_id = m.id
FROM public.sp_municipalities m
WHERE c.state = 'SP'
  AND c.sp_municipality_id IS NULL
  AND c.name = m.name;